import Foundation

func dnsTypeName(_ type: Int) -> String {
    [1: "A", 2: "NS", 5: "CNAME", 6: "SOA", 12: "PTR", 15: "MX", 16: "TXT", 28: "AAAA"][type]
        ?? "TYPE\(type)"
}

func dnsRcodeName(_ code: Int) -> String {
    let names = ["NoError", "FormErr", "ServFail", "NXDomain", "NotImp", "Refused"]
    return code < names.count ? names[code] : "RCODE\(code)"
}

func dnsLabelText(_ bytes: [UInt8]) -> String {
    bytes.map { byte in
        if (33...126).contains(byte) && byte != 46 && byte != 92 {
            return String(UnicodeScalar(Int(byte))!)
        }
        return "\\" + String(format: "%03d", Int(byte))
    }.joined()
}

func ipv6Notation(_ bytes: [UInt8]) -> String {
    let groups = stride(from: 0, to: 16, by: 2).map { readInteger(bytes, $0, 2) }
    var bestStart: Int?
    var bestLength = 1
    var index = 0
    while index < groups.count {
        if groups[index] != 0 {
            index += 1
            continue
        }
        var end = index
        while end < groups.count && groups[end] == 0 { end += 1 }
        if end - index > bestLength {
            bestStart = index
            bestLength = end - index
        }
        index = end
    }
    let texts = groups.map { String($0, radix: 16) }
    guard let start = bestStart else { return texts.joined(separator: ":") }
    return texts.prefix(start).joined(separator: ":") + "::"
        + texts.dropFirst(start + bestLength).joined(separator: ":")
}

struct DNSReader {
    let message: [UInt8]

    func chunk(_ position: Int, _ count: Int) throws -> [UInt8] {
        if position + count > message.count { throw Malformed("dns: truncated") }
        return Array(message[position..<(position + count)])
    }

    func integer(_ position: Int, _ count: Int) throws -> Int {
        readInteger(try chunk(position, count), 0, count)
    }

    func name(_ start: Int) throws -> (String, Int) {
        var position = start
        var labels: [String] = []
        var pointers = 0
        var after: Int?
        while true {
            let length = try integer(position, 1)
            if length == 0 {
                if after == nil { after = position + 1 }
                break
            }
            if length >= 192 {
                let low = try integer(position + 1, 1)
                if after == nil { after = position + 2 }
                pointers += 1
                if pointers > 16 { throw Malformed("dns: compression loop") }
                let target = (length - 192) * 256 + low
                if target >= message.count { throw Malformed("dns: pointer out of range") }
                position = target
            } else if length >= 64 {
                throw Malformed("dns: bad label type")
            } else {
                labels.append(dnsLabelText(try chunk(position + 1, length)))
                position += length + 1
            }
        }
        return (labels.isEmpty ? "<root>" : labels.joined(separator: "."), after!)
    }

    func rdata(_ type: Int, _ start: Int, _ length: Int) throws -> (String, Int) {
        switch type {
        case 1:
            return (ipv4Notation(try integer(start, 4)), start + 4)
        case 28:
            return (ipv6Notation(try chunk(start, 16)), start + 16)
        case 2, 5, 12:
            return try name(start)
        case 15:
            let preference = try integer(start, 2)
            let (exchange, end) = try name(start + 2)
            return ("\(preference) \(exchange)", end)
        case 6:
            let (primary, next) = try name(start)
            let (mailbox, last) = try name(next)
            var position = last
            var fields = [primary, mailbox]
            for _ in 0..<5 {
                fields.append(String(try integer(position, 4)))
                position += 4
            }
            return (fields.joined(separator: " "), position)
        default:
            return ("\(length) bytes", start + length)
        }
    }

    func record(_ start: Int, _ section: String, _ layer: Layer) throws -> Int {
        let (recordName, position) = try name(start)
        let fixed = try chunk(position, 10)
        let type = readInteger(fixed, 0, 2)
        let recordClass = readInteger(fixed, 2, 2)
        let ttl = readInteger(fixed, 4, 4)
        let length = readInteger(fixed, 8, 2)
        let dataStart = position + 10
        if dataStart + length > message.count { throw Malformed("dns: truncated") }
        let (text, end) = try rdata(type, dataStart, length)
        if end != dataStart + length { throw Malformed("dns: bad rdata length") }
        let className = recordClass == 1 ? "IN" : "CLASS\(recordClass)"
        layer.add(section, "\(recordName) \(dnsTypeName(type)) \(className) \(ttl) \(text)")
        if section == "dns.answer" && type == 1 { layer.add("dns.a", readInteger(message, dataStart, 4)) }
        return dataStart + length
    }
}

func dissectDNS(_ message: [UInt8]) throws -> Layer {
    let reader = DNSReader(message: message)
    let header = try reader.chunk(0, 12)
    let flags = readInteger(header, 2, 2)
    let counts = stride(from: 4, to: 12, by: 2).map { readInteger(header, $0, 2) }
    let layer = Layer()
    layer.set("dns.id", readInteger(header, 0, 2))
    layer.set("dns.flags", flags)
    layer.set("dns.flags.response", flags / 32768 % 2)
    layer.set("dns.flags.opcode", flags / 2048 % 16)
    layer.set("dns.flags.rcode", flags % 16)
    let countFields = ["dns.count.queries", "dns.count.answers", "dns.count.auth_rr", "dns.count.add_rr"]
    for (field, count) in zip(countFields, counts) { layer.set(field, count) }
    var position = 12
    for _ in 0..<counts[0] {
        let (name, after) = try reader.name(position)
        let tail = try reader.chunk(after, 4)
        layer.add("dns.qry.name", name)
        layer.add("dns.qry.type", readInteger(tail, 0, 2))
        position = after + 4
    }
    for (section, count) in zip(["dns.answer", "dns.authority", "dns.additional"], counts.dropFirst()) {
        for _ in 0..<count { position = try reader.record(position, section, layer) }
    }
    return layer
}

enum AnalysisMark: String, CaseIterable {
    case retransmission
    case outOfOrder = "out_of_order"
    case lostSegment = "lost_segment"
    case duplicateAck = "duplicate_ack"
}

struct Endpoint: Hashable, Comparable {
    let address: Int
    let port: Int?

    static func < (a: Endpoint, b: Endpoint) -> Bool {
        a.address == b.address ? (a.port ?? -1) < (b.port ?? -1) : a.address < b.address
    }
}

struct EndpointPair: Hashable {
    let first: Endpoint
    let second: Endpoint

    init(_ a: Endpoint, _ b: Endpoint) {
        first = min(a, b)
        second = max(a, b)
    }
}

struct ReceivedInterval: Hashable {
    let start: Int
    let size: Int
}

final class PreviousAck {
    let ack: Int
    let window: Int
    let number: Int
    var count = 0

    init(_ ack: Int, _ window: Int, _ number: Int) {
        self.ack = ack
        self.window = window
        self.number = number
    }
}

final class StreamSide {
    let name: String
    var isn: Int?
    var mss: Int?
    var wscale: Int?
    var base: Int?
    var expected: Int?
    var advancedAt: Int?
    var intervals: Set<ReceivedInterval> = []
    var previousAck: PreviousAck?
    var packets = 0
    var payload = 0
    var marks = Dictionary(uniqueKeysWithValues: AnalysisMark.allCases.map { ($0, 0) })

    init(_ name: String) { self.name = name }
}

enum TCPState: String {
    case synSent = "SYN_SENT"
    case synReceived = "SYN_RECEIVED"
    case established = "ESTABLISHED"
    case finWait = "FIN_WAIT"
    case closing = "CLOSING"
    case closed = "CLOSED"
    case reset = "RESET"
}

struct StreamEvent {
    let number: Int
    let side: String
    let mark: AnalysisMark
    let sequence: Int
    let length: Int
}

final class TCPStream {
    let number: Int
    let client: Endpoint
    let server: Endpoint
    var state: TCPState
    var history: [(TCPState, Int)]
    let start: Int
    var end: Int
    var packets = 0
    var bytes = 0
    var syn: Int?
    var synAck: Int?
    var handshakeAck: Int?
    var events: [StreamEvent] = []
    var closer: Int?
    var finalAck: Int?
    let sides = [StreamSide("client"), StreamSide("server")]

    init(_ number: Int, _ client: Endpoint, _ server: Endpoint, _ state: TCPState, _ packet: Packet) {
        self.number = number
        self.client = client
        self.server = server
        self.state = state
        history = [(state, packet.number)]
        start = packet.time
        end = packet.time
    }

    func recordSYN(_ side: Int, _ packet: Packet) {
        sides[side].isn = packet.int("tcp.seq_raw")
        sides[side].mss = packet.numberValue("tcp.options.mss")
        sides[side].wscale = packet.numberValue("tcp.options.wscale")
        if side == 0 { syn = packet.number } else { synAck = packet.number }
    }

    func changeState(_ next: TCPState, _ packet: Int) {
        state = next
        history.append((next, packet))
    }
}

final class StreamTracker {
    var streams: [TCPStream] = []
    var latest: [EndpointPair: Int] = [:]
    let modulus = 1 << 32

    func track(_ packet: Packet) {
        let source = Endpoint(address: packet.int("ip.src"), port: packet.int("tcp.srcport"))
        let destination = Endpoint(address: packet.int("ip.dst"), port: packet.int("tcp.dstport"))
        let syn = packet.int("tcp.flags.syn") == 1
        let ackSet = packet.int("tcp.flags.ack") == 1
        let fin = packet.int("tcp.flags.fin") == 1
        let rst = packet.int("tcp.flags.rst") == 1
        let seq = packet.int("tcp.seq_raw")
        let ack = packet.numberValue("tcp.ack_raw")
        let length = packet.int("tcp.len")
        let window = packet.int("tcp.window")
        let key = EndpointPair(source, destination)
        var stream = latest[key].map { streams[$0] }
        if stream == nil || ((stream!.state == .closed || stream!.state == .reset) && syn && !ackSet) {
            let state: TCPState = syn ? (ackSet ? .synReceived : .synSent) : .established
            let client = syn && ackSet ? destination : source
            let server = syn && ackSet ? source : destination
            let opened = TCPStream(streams.count, client, server, state, packet)
            if syn { opened.recordSYN(ackSet ? 1 : 0, packet) }
            streams.append(opened)
            latest[key] = opened.number
            stream = opened
        }
        let current = stream!
        packet.set("tcp.stream", current.number)
        let sideIndex = source == current.client ? 0 : 1
        let side = current.sides[sideIndex]
        let other = current.sides[1 - sideIndex]
        if side.base == nil { side.base = seq }
        if ackSet && other.base == nil { other.base = ack! }
        let relative = (seq - side.base! + modulus) % modulus
        packet.set("tcp.seq", relative)
        if ackSet { packet.set("tcp.ack", (ack! - other.base! + modulus) % modulus) }
        let size = length + (syn ? 1 : 0) + (fin ? 1 : 0)
        var mark: AnalysisMark?
        if size > 0 {
            if let expected = side.expected, relative != expected {
                if relative > expected {
                    mark = .lostSegment
                } else if side.intervals.contains(ReceivedInterval(start: relative, size: size)) {
                    mark = .retransmission
                } else {
                    mark = packet.time - side.advancedAt! < 3000 ? .outOfOrder : .retransmission
                }
            }
            side.intervals.insert(ReceivedInterval(start: relative, size: size))
            if side.expected == nil || relative + size > side.expected! {
                side.expected = relative + size
                side.advancedAt = packet.time
            }
        } else if ackSet && !rst, let previous = side.previousAck,
            previous.ack == ack! && previous.window == window {
            mark = .duplicateAck
            previous.count += 1
            packet.duplicateAck = (previous.number, previous.count)
        }
        if ackSet && mark != .duplicateAck { side.previousAck = PreviousAck(ack!, window, packet.number) }
        if let mark {
            packet.mark("tcp.analysis." + mark.rawValue)
            side.marks[mark, default: 0] += 1
            current.events.append(StreamEvent(
                number: packet.number, side: side.name, mark: mark, sequence: relative, length: size
            ))
        }
        let scaled = current.sides[0].wscale != nil && current.sides[1].wscale != nil && !syn
        packet.set("tcp.window.calc", scaled ? window * (1 << side.wscale!) : window)
        let state = current.state
        if rst {
            if state != .closed && state != .reset { current.changeState(.reset, packet.number) }
        } else if state == .synSent && sideIndex == 1 && syn && ackSet
            && ack! == (current.sides[0].isn! + 1) % modulus {
            current.changeState(.synReceived, packet.number)
            current.recordSYN(1, packet)
        } else if state == .synReceived && sideIndex == 0 && ackSet && !syn
            && ack! == (current.sides[1].isn! + 1) % modulus {
            current.changeState(.established, packet.number)
            current.handshakeAck = packet.number
        } else if state == .established && fin {
            current.changeState(.finWait, packet.number)
            current.closer = sideIndex
        } else if state == .finWait && fin && sideIndex != current.closer! {
            current.changeState(.closing, packet.number)
            current.finalAck = (seq + length + 1) % modulus
        } else if state == .closing && sideIndex == current.closer! && ackSet && ack! == current.finalAck! {
            current.changeState(.closed, packet.number)
        }
        side.packets += 1
        side.payload += length
        current.packets += 1
        current.bytes += packet.length
        current.end = packet.time
    }
}

enum ConversationKind: Int {
    case ipv4
    case tcp
    case udp
    var name: String { ["ipv4", "tcp", "udp"][rawValue] }
}

enum ConversationKey: Hashable {
    case ipv4(EndpointPair)
    case tcp(Int)
    case udp(EndpointPair)
}

final class Conversation {
    let kind: ConversationKind
    let endpointA: Endpoint
    let endpointB: Endpoint
    let firstNumber: Int
    let firstTime: Int
    var lastTime: Int
    var packetsAToB = 0
    var bytesAToB = 0
    var packetsBToA = 0
    var bytesBToA = 0
    var packets: Int { packetsAToB + packetsBToA }
    var bytes: Int { bytesAToB + bytesBToA }

    init(_ kind: ConversationKind, _ source: Endpoint, _ destination: Endpoint, _ packet: Packet) {
        self.kind = kind
        endpointA = source
        endpointB = destination
        firstNumber = packet.number
        firstTime = packet.time
        lastTime = packet.time
    }

    func count(_ source: Endpoint, _ packet: Packet) {
        if source == endpointA {
            packetsAToB += 1
            bytesAToB += packet.length
        } else {
            packetsBToA += 1
            bytesBToA += packet.length
        }
        lastTime = packet.time
    }
}

func buildConversations(_ packets: [Packet]) -> [Conversation] {
    var table: [ConversationKey: Conversation] = [:]
    for packet in packets where packet.has("ip.src") {
        let sourceIP = packet.int("ip.src")
        let destinationIP = packet.int("ip.dst")
        let sourceAddress = Endpoint(address: sourceIP, port: nil)
        let destinationAddress = Endpoint(address: destinationIP, port: nil)
        var views: [(ConversationKind, ConversationKey, Endpoint, Endpoint)] = [
            (.ipv4, .ipv4(EndpointPair(sourceAddress, destinationAddress)), sourceAddress, destinationAddress)
        ]
        if packet.has("tcp.stream") {
            let source = Endpoint(address: sourceIP, port: packet.int("tcp.srcport"))
            let destination = Endpoint(address: destinationIP, port: packet.int("tcp.dstport"))
            views.append((.tcp, .tcp(packet.int("tcp.stream")), source, destination))
        }
        if packet.has("udp.srcport") {
            let source = Endpoint(address: sourceIP, port: packet.int("udp.srcport"))
            let destination = Endpoint(address: destinationIP, port: packet.int("udp.dstport"))
            views.append((.udp, .udp(EndpointPair(source, destination)), source, destination))
        }
        for (kind, key, source, destination) in views {
            if table[key] == nil { table[key] = Conversation(kind, source, destination, packet) }
            table[key]!.count(source, packet)
        }
    }
    return table.values.sorted { a, b in
        if a.bytes != b.bytes { return a.bytes > b.bytes }
        if a.packets != b.packets { return a.packets > b.packets }
        if a.kind != b.kind { return a.kind.rawValue < b.kind.rawValue }
        return a.firstNumber < b.firstNumber
    }
}

final class EndpointTotals {
    let address: Int
    var txPackets = 0
    var txBytes = 0
    var rxPackets = 0
    var rxBytes = 0
    var packets: Int { txPackets + rxPackets }
    var bytes: Int { txBytes + rxBytes }

    init(_ address: Int) { self.address = address }
}

func buildEndpoints(_ packets: [Packet]) -> [EndpointTotals] {
    var table: [Int: EndpointTotals] = [:]
    for packet in packets where packet.has("ip.src") {
        let source = packet.int("ip.src")
        let destination = packet.int("ip.dst")
        if table[source] == nil { table[source] = EndpointTotals(source) }
        if table[destination] == nil { table[destination] = EndpointTotals(destination) }
        table[source]!.txPackets += 1
        table[source]!.txBytes += packet.length
        table[destination]!.rxPackets += 1
        table[destination]!.rxBytes += packet.length
    }
    return table.values.sorted { a, b in
        if a.bytes != b.bytes { return a.bytes > b.bytes }
        if a.packets != b.packets { return a.packets > b.packets }
        return a.address < b.address
    }
}

import Foundation

final class Packet: FieldStore {
    let number: Int
    let time: Int
    let length: Int
    var data: [UInt8] = []
    var reason: String?
    var badDump = false
    var layers: [String] = []
    var remaining: [UInt8] = []
    var duplicateAck: (number: Int, count: Int)?

    init(_ number: Int, _ time: Int, _ length: Int) {
        self.number = number
        self.time = time
        self.length = length
    }
}

func readLines(_ path: String) throws -> [String] {
    let text = try String(contentsOfFile: path, encoding: .ascii)
    return text.split(separator: "\n", omittingEmptySubsequences: false).dropLast().map(String.init)
}

func lowerHex(_ character: UInt8) -> Bool {
    (48...57).contains(character) || (97...102).contains(character)
}

func loadDump(_ packet: Packet, _ lines: [(Int, String)]) {
    var bytes: [UInt8] = []
    for (number, line) in lines {
        let characters = Array(line.utf8)
        var valid = characters.count >= 8
        if valid {
            valid = characters.prefix(4).allSatisfy(lowerHex) && characters[4] == 32 && characters[5] == 32
        }
        let fields = valid ? String(decoding: characters.dropFirst(6), as: UTF8.self)
            .split(separator: " ", omittingEmptySubsequences: false).map(String.init) : []
        valid = valid && (1...16).contains(fields.count)
            && fields.allSatisfy { $0.utf8.count == 2 && $0.utf8.allSatisfy(lowerHex) }
        if !valid {
            packet.reason = "dump: bad line \(number)"
            packet.badDump = true
            return
        }
        let offset = Int(String(decoding: characters.prefix(4), as: UTF8.self), radix: 16)!
        if offset != bytes.count {
            packet.reason = "dump: offset mismatch at line \(number)"
            packet.badDump = true
            return
        }
        bytes += fields.map { UInt8($0, radix: 16)! }
    }
    if bytes.count != packet.length {
        packet.reason = "dump: length mismatch (header \(packet.length), data \(bytes.count))"
        packet.badDump = true
    } else {
        packet.data = bytes
    }
}

func readCapture(_ path: String) throws -> [Packet] {
    var packets: [Packet] = []
    var dataLines: [[(Int, String)]] = []
    for (index, line) in try readLines(path).enumerated() {
        if line.hasPrefix("PACKET ") {
            let fields = line.split(separator: " ").dropFirst().map { Int($0)! }
            packets.append(Packet(fields[0], fields[1], fields[2]))
            dataLines.append([])
        } else if !line.isEmpty {
            dataLines[dataLines.count - 1].append((index + 1, line))
        }
    }
    for (packet, lines) in zip(packets, dataLines) { loadDump(packet, lines) }
    return packets
}

func hexDumpLines(_ data: [UInt8]) -> [String] {
    stride(from: 0, to: data.count, by: 16).map { offset in
        let piece = data[offset..<min(data.count, offset + 16)]
        let hex = piece.map { String(format: "%02x", Int($0)) }.joined(separator: " ")
        let padding = String(repeating: " ", count: 47 - hex.count)
        let text = String(piece.map { byte -> Character in
            (32...126).contains(byte) ? Character(UnicodeScalar(Int(byte))!) : "."
        })
        return String(format: "%04x", offset) + "  " + hex + padding + "  |" + text + "|"
    }
}

import Foundation

struct Malformed: Error {
    let reason: String
    init(_ reason: String) { self.reason = reason }
}

final class Layer: FieldStore {
    var next: String?
    var payload: [UInt8] = []
    var remaining: [UInt8] = []
}

func readInteger(_ data: [UInt8], _ index: Int, _ count: Int) -> Int {
    var value = 0
    for byte in data[index..<(index + count)] { value = value * 256 + Int(byte) }
    return value
}

func checksumStatus(_ data: [UInt8]) -> String {
    var sum = 0
    for i in stride(from: 0, to: data.count, by: 2) {
        sum += Int(data[i]) * 256 + (i + 1 < data.count ? Int(data[i + 1]) : 0)
    }
    while sum > 65535 { sum = sum % 65536 + sum / 65536 }
    return sum == 65535 ? "good" : "bad"
}

func macNotation(_ value: Int) -> String {
    (0..<6).map { String(format: "%02x", (value >> ((5 - $0) * 8)) & 255) }.joined(separator: ":")
}

func ipv4Notation(_ value: Int) -> String {
    (0..<4).map { String((value >> ((3 - $0) * 8)) & 255) }.joined(separator: ".")
}

func dissectEthernet(_ frame: [UInt8]) throws -> Layer {
    if frame.count < 14 { throw Malformed("eth: truncated") }
    let layer = Layer()
    let type = readInteger(frame, 12, 2)
    layer.set("eth.dst", readInteger(frame, 0, 6))
    layer.set("eth.src", readInteger(frame, 6, 6))
    layer.set("eth.type", type)
    let payload = Array(frame.dropFirst(14))
    if type == 2054 || type == 2048 {
        layer.next = type == 2054 ? "arp" : "ip"
        layer.payload = payload
    } else {
        layer.remaining = payload
    }
    return layer
}

func dissectARP(_ message: [UInt8]) throws -> Layer {
    if message.count < 28 { throw Malformed("arp: truncated") }
    if readInteger(message, 0, 2) != 1 || readInteger(message, 2, 2) != 2048
        || message[4] != 6 || message[5] != 4 {
        throw Malformed("arp: unsupported format")
    }
    let layer = Layer()
    layer.set("arp.opcode", readInteger(message, 6, 2))
    layer.set("arp.src.hw", readInteger(message, 8, 6))
    layer.set("arp.src.ip", readInteger(message, 14, 4))
    layer.set("arp.dst.hw", readInteger(message, 18, 6))
    layer.set("arp.dst.ip", readInteger(message, 24, 4))
    return layer
}

func dissectIPv4(_ datagram: [UInt8]) throws -> Layer {
    let available = datagram.count
    if available < 20 { throw Malformed("ip: truncated header") }
    let version = Int(datagram[0]) / 16
    if version != 4 { throw Malformed("ip: bad version \(version)") }
    let headerLength = Int(datagram[0]) % 16 * 4
    if headerLength < 20 { throw Malformed("ip: bad header length \(headerLength)") }
    if available < headerLength { throw Malformed("ip: truncated header") }
    let total = readInteger(datagram, 2, 2)
    if total < headerLength { throw Malformed("ip: bad total length \(total)") }
    if total > available {
        throw Malformed("ip: truncated (total length \(total), available \(available))")
    }
    let flags = readInteger(datagram, 6, 2)
    let moreFragments = flags / 8192 % 2
    let fragmentOffset = flags % 8192 * 8
    let proto = Int(datagram[9])
    let layer = Layer()
    layer.set("ip.hdr_len", headerLength)
    layer.set("ip.tos", Int(datagram[1]))
    layer.set("ip.len", total)
    layer.set("ip.id", readInteger(datagram, 4, 2))
    layer.set("ip.flags.df", flags / 16384 % 2)
    layer.set("ip.flags.mf", moreFragments)
    layer.set("ip.frag_offset", fragmentOffset)
    layer.set("ip.ttl", Int(datagram[8]))
    layer.set("ip.proto", proto)
    layer.set("ip.checksum", readInteger(datagram, 10, 2))
    layer.set("ip.checksum.status", checksumStatus(Array(datagram.prefix(headerLength))))
    layer.set("ip.src", readInteger(datagram, 12, 4))
    layer.set("ip.dst", readInteger(datagram, 16, 4))
    let payload = Array(datagram[headerLength..<total])
    if moreFragments == 1 || fragmentOffset != 0 {
        layer.mark("ip.fragment")
        layer.remaining = payload
    } else if let next = [1: "icmp", 17: "udp", 6: "tcp"][proto] {
        layer.next = next
        layer.payload = payload
    } else {
        layer.remaining = payload
    }
    return layer
}

import Foundation

enum FieldValue: Equatable {
    case number(Int)
    case text(String)
    case present
}

class FieldStore {
    var fields: [String: [FieldValue]] = [:]

    func has(_ name: String) -> Bool { !(fields[name] ?? []).isEmpty }
    func values(_ name: String) -> [FieldValue] { fields[name] ?? [] }
    func set(_ name: String, _ value: Int) { fields[name] = [.number(value)] }
    func set(_ name: String, _ value: String) { fields[name] = [.text(value)] }
    func mark(_ name: String) { fields[name] = [.present] }
    func add(_ name: String, _ value: Int) { fields[name, default: []].append(.number(value)) }
    func add(_ name: String, _ value: String) { fields[name, default: []].append(.text(value)) }

    func numberValue(_ name: String) -> Int? {
        if case let .number(value)? = fields[name]?.first { return value }
        return nil
    }

    func stringValue(_ name: String) -> String? {
        if case let .text(value)? = fields[name]?.first { return value }
        return nil
    }

    func int(_ name: String) -> Int { numberValue(name)! }

    func strings(_ name: String) -> [String] {
        values(name).compactMap { if case let .text(value) = $0 { return value }; return nil }
    }

    func numbers(_ name: String) -> [Int] {
        values(name).compactMap { if case let .number(value) = $0 { return value }; return nil }
    }
}

